### Task 2: Add Rejection Reason Modal JavaScript to index.html

**File:** `server/templates/index.html`
**Where:** Replace the existing `showRejectModal()` function (lines 701-706).

**Replace:**
```javascript
function showRejectModal() {
    var reason = prompt('Rejection reason (optional):');
    if (reason === null) return;
    var targetStage = _modalStage === 'awaiting-human-approval' ? 'ideas' : 'rejected';
    approveFeature(targetStage, reason || 'No reason given');
}
```

**With:**
```javascript
function showRejectModal() {
    document.getElementById('reject-reason-input').value = '';
    document.getElementById('reject-reason-modal').classList.add('active');
}
function closeRejectReasonModal(event) {
    if (!event || event.target === document.getElementById('reject-reason-modal')) {
        document.getElementById('reject-reason-modal').classList.remove('active');
    }
}
function confirmReject() {
    var reason = document.getElementById('reject-reason-input').value.trim();
    var targetStage = _modalStage === 'awaiting-human-approval' ? 'ideas' : 'rejected';
    closeRejectReasonModal();
    approveFeature(targetStage, reason || 'No reason given');
}
```

**Depends on:** Task 1 (modal HTML must exist).

