### Task 4: Modify moveFeature() in index.html to use modal instead of confirm()

**File:** `server/templates/index.html`
**Where:** Modify the `moveFeature()` function (lines 743-777).

**Replace the confirm() call and restructure:**

The current function does `if (!confirm('Move this item to "' + targetStage + '"?')) return;` and then immediately executes the fetch.

Change to:
1. Remove the `confirm()` call from `moveFeature()`
2. Instead, show the move-confirm-modal with the target stage name in the message
3. Store the target stage in a module-level variable `_pendingMoveStage`
4. Add `closeMoveConfirmModal(event)` and `confirmMoveFeature()` functions

**Replace the moveFeature function:**
```javascript
var _pendingMoveStage = null;
function moveFeature() {
    var select = document.getElementById('move-stage-select');
    var targetStage = select.value;
    if (!targetStage) return;
    _pendingMoveStage = targetStage;
    document.getElementById('move-confirm-message').textContent = 'Move this item to "' + targetStage + '"?';
    document.getElementById('move-confirm-modal').classList.add('active');
}
function closeMoveConfirmModal(event) {
    if (!event || event.target === document.getElementById('move-confirm-modal')) {
        document.getElementById('move-confirm-modal').classList.remove('active');
        _pendingMoveStage = null;
    }
}
function confirmMoveFeature() {
    var targetStage = _pendingMoveStage;
    closeMoveConfirmModal();
    if (!targetStage) return;
    var feedbackEl = document.getElementById('move-feedback');
    var btn = document.getElementById('btn-move');
    feedbackEl.textContent = 'Moving...';
    feedbackEl.style.color = '#8b949e';
    btn.disabled = true;
    fetch('/api/clients/' + encodeURIComponent(_modalClientId) + '/features/' + encodeURIComponent(_modalFeatureId) + '/move?key=' + encodeURIComponent(key), {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({target_stage: targetStage})
    }).then(function(r) {
        return r.json().then(function(data) {
            if (r.ok) {
                feedbackEl.style.color = '#3fb950';
                feedbackEl.textContent = 'Moved to ' + targetStage + '!';
                setTimeout(function() {
                    closeModal();
                    smartPollBoard();
                }, 1000);
            } else {
                feedbackEl.style.color = '#f85149';
                feedbackEl.textContent = data.error || 'Move failed';
                btn.disabled = false;
            }
        });
    }).catch(function() {
        feedbackEl.style.color = '#f85149';
        feedbackEl.textContent = 'Network error';
        btn.disabled = false;
    });
}
```

**Depends on:** Task 3 (modal HTML must exist).

