### Task 8: Modify moveFeatureDropdown() in client.html to use modal instead of confirm()

**File:** `server/templates/client.html`
**Where:** Modify the `moveFeatureDropdown()` function (lines 1173-1207).

Same pattern as Task 4 but adapted for client.html conventions:
- Uses `_clientID` instead of `_modalClientId`
- Uses `_detailFeatureId` instead of `_modalFeatureId`
- Uses `_dashKey` instead of `key`
- Success callback calls `smartPollFeatures()` instead of `closeModal(); smartPollBoard();`
- Add `_pendingMoveStage` variable, `closeMoveConfirmModal()`, and `confirmMoveFeature()` functions

```javascript
var _pendingMoveStage = null;
function moveFeatureDropdown() {
    var select = document.getElementById('move-stage-select');
    var targetStage = select.value;
    if (!targetStage) return;
    _pendingMoveStage = targetStage;
    document.getElementById('move-confirm-message').textContent = 'Move this item to "' + targetStage + '"?';
    document.getElementById('move-confirm-modal').classList.add('active');
}
function closeMoveConfirmModal(event) {
    if (!event || event.target === document.getElementById('move-confirm-modal')) {
        document.getElementById('move-confirm-modal').classList.remove('active');
        _pendingMoveStage = null;
    }
}
function confirmMoveFeature() {
    var targetStage = _pendingMoveStage;
    closeMoveConfirmModal();
    if (!targetStage) return;
    var featureID = _detailFeatureId;
    var feedback = document.getElementById('move-feedback');
    var btn = document.getElementById('btn-move');
    feedback.textContent = 'Moving...';
    feedback.style.color = '#8b949e';
    btn.disabled = true;
    fetch('/api/clients/' + encodeURIComponent(_clientID) + '/features/' + encodeURIComponent(featureID) + '/move?key=' + encodeURIComponent(_dashKey), {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({target_stage: targetStage})
    }).then(function(resp) {
        return resp.json().then(function(data) { return {ok: resp.ok, data: data}; });
    }).then(function(result) {
        if (result.ok) {
            feedback.style.color = '#3fb950';
            feedback.textContent = 'Moved to ' + targetStage + '!';
            setTimeout(function() {
                smartPollFeatures();
            }, 1000);
        } else {
            feedback.style.color = '#f85149';
            feedback.textContent = result.data.error || 'Move failed';
            btn.disabled = false;
        }
    }).catch(function() {
        feedback.style.color = '#f85149';
        feedback.textContent = 'Network error';
        btn.disabled = false;
    });
}
```

**Depends on:** Task 7.

